SET NOCOUNT ON;
SELECT 'USERS',COUNT_BIG(*),CHECKSUM_AGG(BINARY_CHECKSUM(*)) FROM USERS WHERE email NOT LIKE 'TWMGRDEMO%@example.invalid'
UNION ALL SELECT 'STORES',COUNT_BIG(*),CHECKSUM_AGG(BINARY_CHECKSUM(*)) FROM STORES WHERE slug<>'TWMGRDEMO-store'
UNION ALL SELECT 'PRODUCTS',COUNT_BIG(*),CHECKSUM_AGG(BINARY_CHECKSUM(*)) FROM PRODUCTS WHERE slug NOT LIKE 'TWMGRDEMO-%'
UNION ALL SELECT 'ORDERS',COUNT_BIG(*),CHECKSUM_AGG(BINARY_CHECKSUM(*)) FROM ORDERS WHERE order_code NOT LIKE 'TWMGRDEMO-%';
SELECT 'ORDER_ITEMS',COUNT_BIG(*),CHECKSUM_AGG(BINARY_CHECKSUM(*)) FROM ORDER_ITEMS WHERE order_id IN(SELECT id FROM ORDERS WHERE order_code NOT LIKE 'TWMGRDEMO-%');
SELECT 'PAYMENTS',COUNT_BIG(*),CHECKSUM_AGG(BINARY_CHECKSUM(*)) FROM PAYMENTS WHERE order_id IN(SELECT id FROM ORDERS WHERE order_code NOT LIKE 'TWMGRDEMO-%');
SELECT 'SUPPORT_CONVERSATIONS',COUNT_BIG(*),CHECKSUM_AGG(BINARY_CHECKSUM(*)) FROM SUPPORT_CONVERSATIONS WHERE user_email NOT LIKE 'TWMGRDEMO%@example.invalid';
